//! How a command-line client splits a script into statements.
//!
//! Some SQL is never sent to the server as written. A command-line client
//! reads the script line by line, splits it into statements itself and handles
//! some of the text before anything reaches the server. [`ClientCommandRules`]
//! describes a client. The lexer's `client_script` module lexes with it, and
//! `sqlfluff.core.parser.client_commands` is the Python equivalent: the two
//! must emit identical tokens.
//!
//! Dialects get their rules from code generated by `utils/build_lexers.py`, so
//! everything here is `'static` and can be built in a `static`.

/// What a client command does, which decides how its text is lexed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CommandEffect {
    /// Changes the statement delimiter, e.g. `DELIMITER $$`.
    SetDelimiter,
    /// Runs another script, e.g. `SOURCE file.sql`.
    ReadFile,
    /// Sends the statement so far, as the delimiter does, e.g. `\g`.
    EndStatement,
}

/// One row of a client's command table.
#[derive(Debug, Clone, Copy)]
pub struct ClientCommand {
    pub effect: CommandEffect,
    /// The long form in lower case, e.g. `delimiter`, matched in any case.
    ///
    /// It is a command only at the start of a statement. `None` for a command
    /// whose long form can't usefully appear in a script.
    pub name: Option<&'static str>,
    /// The short form, e.g. `\d`, matched in its own case.
    ///
    /// It is a command anywhere outside strings and comments.
    pub shorthand: Option<&'static str>,
}

/// How a command-line client splits a script into statements.
#[derive(Debug, Clone, Copy)]
pub struct ClientCommandRules {
    pub commands: &'static [ClientCommand],
    /// Lexer matchers whose text the client doesn't scan: strings, quoted
    /// identifiers and comments. The delimiter isn't found inside these.
    pub opaque_token_names: &'static [&'static str],
    /// Whether a `/* ... */` comment may come before a command on its line.
    pub command_after_block_comment: bool,
    /// Whether `--` starts a comment at the start of a statement even with no
    /// whitespace after it. Elsewhere `--` needs whitespace or the end of the
    /// line after it, which is the dialect's comment matcher's job.
    pub dash_dash_comment_at_statement_start: bool,
    pub default_delimiter: &'static str,
    /// Longer delimiters are cut to this many bytes, as the client does.
    pub max_delimiter_bytes: usize,
}

impl ClientCommandRules {
    /// The command whose long form is `name`, in any case.
    #[must_use]
    pub fn command_named(&self, name: &str) -> Option<&ClientCommand> {
        self.commands.iter().find(|command| {
            command
                .name
                .is_some_and(|long| long.eq_ignore_ascii_case(name))
        })
    }

    /// The command whose short form starts `text`.
    #[must_use]
    pub fn command_starting(&self, text: &str) -> Option<&ClientCommand> {
        self.commands.iter().find(|command| {
            command
                .shorthand
                .is_some_and(|shorthand| text.starts_with(shorthand))
        })
    }

    /// Whether the client scans the text of tokens from the matcher `name`.
    #[must_use]
    pub fn is_opaque(&self, name: &str) -> bool {
        self.opaque_token_names.contains(&name)
    }
}
